<template><section class="platform-laboratories-view"><p v-if="error" class="platform-error" role="alert">{{ error }}</p><div v-if="createdAccessUrls" class="platform-success" role="status"><strong>Laboratorio registrado.</strong><span>Acceso de desarrollo: <a :href="createdAccessUrls.development" target="_blank" rel="noopener noreferrer">{{ createdAccessUrls.development }}</a></span><span>Acceso canónico: <a :href="createdAccessUrls.canonical" target="_blank" rel="noopener noreferrer">{{ createdAccessUrls.canonical }}</a></span><button type="button" class="secondary-button" @click="createdAccessUrls = null">Cerrar</button></div><BioNexusDataGrid v-model:search-model-value="search" :row-data="laboratories" :column-defs="columnDefs" :get-row-id="getRowId" search-enabled refresh-enabled :refreshing="loading" empty-text="No existen laboratorios registrados." @refresh="load"><template #actions><BioNexusActionButton label="Registrar laboratorio" icon="add" variant="primary" @click="provisioningDialog.open()"/></template></BioNexusDataGrid><PlatformLaboratoryDialog ref="provisioningDialog" @created="handleCreated"/></section></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import BioNexusDataGrid from '@/components/grid/BioNexusDataGrid.vue';import BioNexusActionButton from '@/components/ui/BioNexusActionButton.vue';import PlatformLaboratoryDialog from '@/components/platform/PlatformLaboratoryDialog.vue';import { getPlatformLaboratories } from '@/services/platformService';
const laboratories=ref([]),loading=ref(false),error=ref(''),search=ref(''),provisioningDialog=ref(null),createdAccessUrls=ref(null);const columnDefs=computed(()=>[{headerName:'RIF',field:'rif',minWidth:150},{headerName:'Nombre',field:'name',minWidth:190,flex:1},{headerName:'Razón social',field:'businessName',minWidth:220,flex:1},{headerName:'Dirección',field:'address',minWidth:240,flex:1},{headerName:'Sucursales',field:'branchCount',width:120,filter:'agNumberColumnFilter'},{headerName:'Paquetes de catálogo',field:'catalogPackageCount',width:180,filter:'agNumberColumnFilter'},{headerName:'Módulos',field:'moduleCount',width:110,filter:'agNumberColumnFilter'}]);const getRowId=params=>String(params.data.id);async function load(){loading.value=true;error.value='';try{laboratories.value=await getPlatformLaboratories()}catch{error.value='No fue posible cargar los laboratorios.'}finally{loading.value=false}}async function handleCreated(result){createdAccessUrls.value=result?.accessUrls||null;await load()}onMounted(load);
</script><style scoped>.platform-laboratories-view{display:grid;gap:var(--bio-nexus-space-3);min-width:0}.platform-error{margin:0;padding:12px;border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-danger-soft);color:var(--bio-nexus-color-danger)}.platform-success{display:grid;gap:6px;padding:12px;border:1px solid var(--bio-nexus-color-success);border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-success-soft);color:var(--bio-nexus-color-text-primary);overflow-wrap:anywhere}.platform-success span{font-size:13px}.platform-success button{justify-self:end}</style>
